{"explanation":"Area is two-dimensional. Scaling by k stretches every length by k, so both the base and the height grow by k, and the area grows by k × k = k². The picture shows this directly: when k is a whole number, the scaled triangle splits into exactly k² copies of the original. There are k(k+1)/2 upright copies (blue) and k(k−1)/2 upside-down copies (teal), which add up to k². Move the slider and count the pieces. The rule works for any k, including fractions, because the area formula ½·base·height multiplies two lengths that each grow by k.","manimCode":"const e1 = [1.0, 0, 0];
const e2 = [0.35, 0.9, 0];
const origO = [-5.6, -1.2, 0];
const bigO = [-1.2, -3.0, 0];

function pt(O, i, j, s) {
  return [O[0] + s * (i * e1[0] + j * e2[0]), O[1] + s * (i * e1[1] + j * e2[1]), 0];
}

const title = new MathTex({ latex: '\\text{Area}_{\\text{scaled}} = k^2 \\cdot \\text{Area}_{\\text{original}}' });
await title.waitForRender();
title.moveTo([0, 3.2, 0]);
scene.add(title);

const orig = new Polygon({ vertices: [pt(origO, 0, 0, 1), pt(origO, 1, 0, 1), pt(origO, 0, 1, 1)], color: YELLOW });
orig.setFill(BLUE, 0.6);
scene.add(orig);
const origLabel = new Text({ text: 'original (area A)', color: YELLOW, fontSize: 22 });
origLabel.moveTo([-5.0, 0.1, 0]);
scene.add(origLabel);

let tiles = null;
let outline = null;
let info = null;
let info2 = null;

function build(k) {
  if (tiles) scene.remove(tiles);
  if (outline) scene.remove(outline);
  if (info) scene.remove(info);
  if (info2) scene.remove(info2);
  const arr = [];
  for (let i = 0; i < k; i++) {
    for (let j = 0; j < k - i; j++) {
      const up = new Polygon({ vertices: [pt(bigO, i, j, 1), pt(bigO, i + 1, j, 1), pt(bigO, i, j + 1, 1)], color: WHITE });
      up.setFill(BLUE, 0.6);
      up.setStrokeWidth(2);
      makeHoverable(up, scene, { hoverScale: 1.05 });
      arr.push(up);
      if (i + j <= k - 2) {
        const dn = new Polygon({ vertices: [pt(bigO, i + 1, j, 1), pt(bigO, i + 1, j + 1, 1), pt(bigO, i, j + 1, 1)], color: WHITE });
        dn.setFill(TEAL, 0.6);
        dn.setStrokeWidth(2);
        makeHoverable(dn, scene, { hoverScale: 1.05 });
        arr.push(dn);
      }
    }
  }
  tiles = new VGroup(...arr);
  outline = new Polygon({ vertices: [pt(bigO, 0, 0, k), pt(bigO, 1, 0, k), pt(bigO, 0, 1, k)], color: YELLOW });
  outline.setFillOpacity(0);
  outline.setStrokeWidth(5);
  scene.add(tiles, outline);
  const up = k * (k + 1) / 2, dn = k * (k - 1) / 2;
  info = new Text({ text: 'k = ' + k + ':  ' + up + ' upright + ' + dn + ' flipped = ' + (k * k) + ' copies', color: WHITE, fontSize: 24 });
  info.moveTo([0, 2.3, 0]);
  info2 = new Text({ text: 'base ×' + k + ',  height ×' + k + '  →  area ×' + (k * k), color: GOLD, fontSize: 24 });
  info2.moveTo([0, 1.75, 0]);
  scene.add(info, info2);
}

build(1);
await scene.wait(0.6);
build(2);
await scene.wait(0.8);
build(3);

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Scale factor k', min: 1, max: 4, value: 3, step: 1, onChange: (v) => { build(Math.round(v)); } });

await scene.wait(999999);"}

